      String secret = SECRETS[new Random().nextInt(SECRETS.length)];	//fqn: java.util.Random.nextInt

      MessageDigest md = MessageDigest.getInstance("MD5");	//fqn: java.security.MessageDigest.getInstance
      md.update(secret.getBytes());	//fqn: java.lang.String.getBytes
      byte[] digest = md.digest();	//fqn: java.security.MessageDigest.digest
      md5Hash = DatatypeConverter.printHexBinary(digest).toUpperCase();	//fqn: DatatypeConverter.printHexBinary
      request.getSession().setAttribute("md5Hash", md5Hash);	//fqn: request.getSession
      request.getSession().setAttribute("md5Secret", secret);	//fqn: request.getSession
    }
    return md5Hash;
  }

