    try (ObjectInputStream ois =
        new ObjectInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(b64token)))) {	//fqn: java.util.Base64.Decoder.decode
      before = System.currentTimeMillis();	//fqn: java.lang.System.currentTimeMillis
      Object o = ois.readObject();	//fqn: java.io.ObjectInputStream.readObject
      if (!(o instanceof VulnerableTaskHolder)) {
