  public static boolean verifyMessage(
      String message, String base64EncSignature, PublicKey publicKey) {

    log.debug("start verifyMessage");	//fqn: log.debug
    boolean result = false;

    try {

      base64EncSignature = base64EncSignature.replace("\r", "").replace("\n", "").replace(" ", "");	//fqn: java.lang.String.replace
      // get raw signature from base64 encrypted string in header
      byte[] decodedSignature = Base64.getDecoder().decode(base64EncSignature);	//fqn: java.util.Base64.Decoder.decode

      // Initiate signature verification
      Signature instance = Signature.getInstance("SHA256withRSA");	//fqn: java.security.Signature.getInstance
      instance.initVerify(publicKey);	//fqn: java.security.Signature.initVerify
      instance.update(message.getBytes("UTF-8"));	//fqn: java.lang.String.getBytes

      // actual verification against signature
      result = instance.verify(decodedSignature);	//fqn: java.security.Signature.verify

      log.info("Verified the signature with result: {}", result);	//fqn: log.info
    } catch (Exception e) {
      log.error("Signature verification failed", e);	//fqn: log.error
    }

    log.debug("end verifyMessage");	//fqn: log.debug
    return result;
  }

